  auto _INITIAL_STATE = _o->INITIAL_STATE.empty() ? 0 : _fbb.CreateString(_o->INITIAL_STATE);
  auto _EPOCH_MS = _o->EPOCH_MS;
  auto _MANEUVER_PLAN = _o->MANEUVER_PLAN.empty() ? 0 : _fbb.CreateString(_o->MANEUVER_PLAN);
  auto _CONJUNCTION_PRIMARY = _o->CONJUNCTION_PRIMARY.empty() ? 0 : _fbb.CreateString(_o->CONJUNCTION_PRIMARY);
  auto _CONJUNCTION_SECONDARY = _o->CONJUNCTION_SECONDARY.empty() ? 0 : _fbb.CreateString(_o->CONJUNCTION_SECONDARY);
  auto _OBSERVATIONS = _o->OBSERVATIONS.size() ? _fbb.CreateVectorOfStrings(_o->OBSERVATIONS) : 0;
  auto _OD_CONFIG = _o->OD_CONFIG.empty() ? 0 : _fbb.CreateString(_o->OD_CONFIG);
  auto _GROUND_STATION = _o->GROUND_STATION.empty() ? 0 : _fbb.CreateString(_o->GROUND_STATION);
  auto _FORMATION_CONFIG = _o->FORMATION_CONFIG.empty() ? 0 : _fbb.CreateString(_o->FORMATION_CONFIG);
